预防心理健康危机
预防心理健康危机需要主动关注你的情感福祉，并发展早期预警系统，帮助你在问题变得严重之前识别它们。

早期预警信号
学会识别你的心理健康可能下降的早期预警信号。这些可能包括睡眠模式、食欲、能量水平或情绪的变化；易怒或焦虑增加；难以集中注意力或做决定；或从社交活动和关系中退缩。

